// Centralized configuration & secrets (hardcoded per request)
// TODO: USE N8N CREDENTIALS for tokens/keys in production
/* SANDBOX CONFIG */
const CONFIG = {
  pdfMonkey: {
    token: '2zpxHdmsse2ECXgVVtVR',
    // interior template (expects pages_html)
    templateId: '5539DDB4-EC78-4AE9-A3FB-DB1E7F8DD172'
  },
  lulu: {
    apiBase: 'https://api.sandbox.lulu.com',
    clientKey: '9b388aaa-f0c9-448d-b3d1-8561a8cf2094',
    clientSecret: '3fsYZ7GbbXvdQhsOSxstzIbqdbdJMMtS',
    basicAuth: null
  },
  supabase: {
    projectUrl: 'https://mdnthwpcnphjnnblbvxk.supabase.co',
    serviceRoleKey: 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im1kbnRod3BjbnBoam5uYmxidnhrIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2MDUwMDc4MCwiZXhwIjoyMDc2MDc2NzgwfQ.wNVQ3U2nWTGu8VsuXKasWOCxVhpca5x42wSapQDinGs'
  },
  r2: {
    bucket: 'little-hero-orders',
    endpointHost: '3daae940fcb6fc5b8bbd9bb8fcc62854.r2.cloudflarestorage.com',
    region: 'auto',
    accessKeyId: '320e3b8228c5ff7bd2395043886f03d3',
    secretAccessKey: 'a1ba025ddbe2d8ef7032d2d6635dce3b6fbc4bdbf9c19c68d0b0bd566c989572'
  },
  defaults: {
    debug: false,
    testMode: false,
    // 🔑 Lulu POD package (8.5x8.5, premium-color, perfect-bound, 80# text, matte)
    podPackageId: '0850X0850FCPREPB080CW444MXX',
    trimIn: {
      w: 8.5, h: 8.5,
      assetBase: 'https://admin.littleherolabs.com/api/assets/',
      podPackageId: null // kept null; top-level defaults.podPackageId is source of truth
    },
    bleedIn: { w: 8.75, h: 8.75 },
    print: {
      color: 'premium-color',
      stock: '80#-text',
      binding: 'perfect-bound',
      coverFinish: 'matte'
    },
    quantity: 1,
    shippingLevel: 'STANDARD'
  }
};

// --- derive basicAuth from client credentials (computed here to avoid expression quirks) ---
try {
  const k = CONFIG?.lulu?.clientKey || '';
  const s = CONFIG?.lulu?.clientSecret || '';
  const b = Buffer.from(`${k}:${s}`).toString('base64');
  if (!CONFIG.lulu) CONFIG.lulu = {};
  CONFIG.lulu.basicAuth = 'Basic ' + b;
} catch (e) {
  // leave basicAuth as-is if Buffer not available (should be available in Code nodes)
}


return [{ json: { CONFIG } }];

// Validate & normalize W4 intake payload + attach CONFIG
// Robust to multiple inbound items (simulator + config); tolerant of amazonOrderId variants.

// --- helpers ---
function latestFrom(nodeName){
  // Try without runIndex (latest), then with current runIndex as fallback
  try {
    const arr = $items(nodeName) || [];
    if (Array.isArray(arr) && arr.length) return arr[arr.length - 1].json || null;
  } catch {}
  try {
    const arr = $items(nodeName, 0, $runIndex) || [];
    if (Array.isArray(arr) && arr.length) return arr[arr.length - 1].json || null;
  } catch {}
  return null;
}
function firstNonEmpty(...vals){
  for (const v of vals){
    if (v === undefined || v === null) continue;
    const s = typeof v === 'string' ? v.trim() : v;
    if (s !== '' && s !== undefined && s !== null) return s;
  }
  return undefined;
}
function looksLikeW4(o){
  if (!o || typeof o !== 'object') return false;
  return !!(o.orderId || o.amazonOrderId || o.AmazonOrderId || o.amazon_order_id || o.meta?.orderId);
}

// --- collect all inbound JSONs (any wiring order) ---
let inbound = [];
try { inbound = $input.all().flat().map(it => it?.json || {}); } catch {}
const named = [
  latestFrom('Simulate Webhook'),
  latestFrom('Webhook (W4 Intake)'),
].filter(Boolean);

const allJsons = [...inbound, ...named, ($json || {})];

// --- resolve CONFIG from any source (merge for safety) ---
const cfgCandidates = [];
const cfgInboundHit = allJsons.find(o => o && o.CONFIG);
if (cfgInboundHit?.CONFIG) cfgCandidates.push(cfgInboundHit.CONFIG);
const cfgSandbox = latestFrom('Config (W4) — SANDBOX')?.CONFIG;
if (cfgSandbox) cfgCandidates.push(cfgSandbox);
const cfgProd = latestFrom('Config (W4) — PRODUCTION')?.CONFIG;
if (cfgProd) cfgCandidates.push(cfgProd);
if ($json.CONFIG) cfgCandidates.push($json.CONFIG);

// Merge in order; later candidates can fill gaps
const cfg = Object.assign({}, ...cfgCandidates);

// --- pick the payload that actually has an order id ---
const candidate = allJsons.find(looksLikeW4) || {};

// --- normalize core fields ---
const orderId = String(firstNonEmpty(
  candidate.orderId,
  candidate.amazonOrderId,
  candidate.AmazonOrderId,
  candidate.amazon_order_id,
  candidate.meta?.orderId
) || '').trim();

let pageImageUrls = Array.isArray(candidate.pageImageUrls) ? candidate.pageImageUrls : [];
const coverPdfR2Key = firstNonEmpty(candidate.coverPdfR2Key) || null;
const coverPdfUrl   = firstNonEmpty(candidate.coverPdfUrl)   || null;

// --- optional context ---
const shippingAddress = candidate.shippingAddress || candidate.shipping_address || {};
const customer = candidate.customer || {
  email: candidate.customer_email,
  name:  candidate.customer_name
};
const title = firstNonEmpty(candidate.title, 'Little Hero Book');

// --- validations ---
if (!orderId) {
  const inboundSummary = allJsons.map((o, i) => ({ idx: i, keys: Object.keys(o || {}) }));
  throw new Error(`W4 validation: Missing orderId from W3 → W4. Debug: ${JSON.stringify(inboundSummary)}`);
}
if (!Array.isArray(pageImageUrls)) {
  throw new Error('W4 validation: pageImageUrls must be an array');
}
if (pageImageUrls.length !== 15) {
  throw new Error(`W4 validation: expected exactly 15 pageImageUrls (p00..p14); received ${pageImageUrls.length}`);
}

// --- normalize + add cache-buster so PDFMonkey fetches latest bytes ---
const bustSeed = firstNonEmpty(candidate.runStamp, candidate.runId, cfg.runStamp, orderId, Date.now());
const BUST = encodeURIComponent(String(bustSeed));
pageImageUrls = pageImageUrls.map((u, i) => {
  const s = String(u || '').trim();
  if (!s) throw new Error(`W4 validation: pageImageUrls[${i}] is empty`);
  return s + (s.includes('?') ? '&' : '?') + 'v=' + BUST;
});

// --- derived keys for interior PDF output ---
const pdfFilename = `interior_${orderId}.pdf`;
const pdfR2Key    = `book-mvp-simple-adventure/orders/${orderId}/${pdfFilename}`;

// --- output ---
return [{
  json: {
    CONFIG: cfg,
    orderId,
    pageImageUrls,
    coverPdfR2Key,
    coverPdfUrl,
    shippingAddress,
    customer,
    title,
    pdfFilename,
    pdfR2Key
  }
}];

// Build pages_html for PDFMonkey at 8.75×8.75 in (bleed) from pageImageUrls
const j = $input.first().json || {};
const pages = Array.isArray(j.pageImageUrls) ? j.pageImageUrls : [];
if (pages.length === 0) throw new Error('No pageImageUrls to build pages_html');

const css = `
  <style>
    @page { size: 8.75in 8.75in; margin: 0; }
    html, body { margin:0; padding:0; }
    .page { width:8.75in; height:8.75in; page-break-after: always; }
    .bg { width:100%; height:100%; object-fit: cover; display:block; }
  </style>
`;

const pagesHtml = pages.map(url => {
  return `<section class="page"><img class="bg" src="${url}" alt="" /></section>`;
}).join('\n');

// Preserve upstream context and attach pages_html at top-level
const ctx = $input.first().json || {};
return [{
  json: {
    ...ctx,
    pages_html: `${css}\n${pagesHtml}`
  }
}];

const d = $input.first().json;
const tpl = d.CONFIG?.pdfMonkey?.templateId;
if (!tpl || tpl === 'REPLACE_WITH_PDFMONKEY_TEMPLATE_ID') {
  throw new Error('Missing PDFMonkey templateId in Config (W4). Please set CONFIG.pdfMonkey.templateId');
}
return [{
  json: {
    ...d,
    document: {
      document_template_id: tpl,
      status: 'pending',
      meta: { _filename: d.pdfFilename },
      payload: { pages_html: d.pages_html }
    }
  }
}];

const createResp = $input.first().json;
const doc = createResp.data || createResp.document || createResp;
const docId = doc.id || doc.data?.id;
if (!docId) throw new Error('PDFMonkey create response missing id');

const http = this.helpers.httpRequest;
const token = $json.CONFIG?.pdfMonkey?.token; if (!token) { throw new Error('Missing PDFMonkey token in CONFIG'); }
const AUTH_HEADER = { Authorization: `Bearer ${token}` };

let status = doc.status || 'queued';
let downloadUrl = doc.download_url || null;
let attempts = 0;
async function sleep(ms){ return new Promise(r=>setTimeout(r, ms)); }

while (attempts < 20) {
  if (status === 'success' && downloadUrl) break;
  const resp = await http({ method:'GET', url:`https://api.pdfmonkey.io/api/v1/documents/${docId}`, json:true, headers: AUTH_HEADER });
  const d = resp.data || resp.document || resp;
  status = d.status;
  downloadUrl = d.download_url || d.file_url || null;
  if (status === 'success' && downloadUrl) break;
  attempts++; const delay = Math.min(6000, 2000 * (1 + attempts/3)); await sleep(delay);
}
if (status !== 'success' || !downloadUrl) throw new Error(`PDF not ready (status=${status})`);

const orderId = $json.orderId;
const pdfFilename = $json.pdfFilename || `interior_${orderId}.pdf`;
const pdfR2Key = `book-mvp-simple-adventure/orders/${orderId}/${pdfFilename}`;
return [{ json: { ...$json, pdfMonkeyDocumentId: docId, pdfDownloadUrl: downloadUrl, pdfR2Key } }];

/**
 * Prepare PDF Metadata for Merge — resilient to S3 node dropping context
 */
function latest(node) {
  try { return ($items(node, 0, $runIndex)?.[0]?.json) || null; } catch { return null; }
}

const s3Out = $input.first()?.json || {};

// Reattach context from earlier nodes (first hit wins)
const ctx =
  latest('Poll PDFMonkey until ready') ||
  latest('Reattach Context (PDFM)') ||
  latest('Build Pages HTML (8.75in)') ||
  latest('Validate & Normalize W4 Input') ||
  s3Out || {};

const orderId     = ctx.orderId || null;
const pdfFilename = ctx.pdfFilename || (orderId ? `interior_${orderId}.pdf` : null);
const pdfR2Key    = ctx.pdfR2Key || (orderId && pdfFilename
                    ? `book-mvp-simple-adventure/orders/${orderId}/${pdfFilename}`
                    : null);

if (!orderId || !pdfFilename || !pdfR2Key) {
  throw new Error(`Missing required PDF metadata: orderId=${orderId}, pdfFilename=${pdfFilename}, pdfR2Key=${pdfR2Key}`);
}

return [{
  json: {
    ...ctx,           // full upstream context (orderId, pdfR2Key, etc.)
    ...s3Out,         // anything S3 returned
    pdfComplete: true,
    pdfUploadedAt: new Date().toISOString()
  }
}];

const j = $input.first().json || {};
const cfg = j.CONFIG || {};
const dflt = cfg.defaults || {};

/**
 * Determine shipping_level (map legacy -> allowed)
 * Allowed: MAIL | PRIORITY_MAIL | GROUND | EXPEDITED | EXPRESS
 */
function normalizeShip(level) {
  const raw = String(level || '').toUpperCase();
  if (raw === 'STANDARD') return 'GROUND';
  const allowed = new Set(['MAIL','PRIORITY_MAIL','GROUND','EXPEDITED','EXPRESS']);
  return allowed.has(raw) ? raw : 'GROUND';
}

const qty = Number(j.printOptions?.quantity ?? dflt.quantity ?? 1);
const shipping_level = normalizeShip(j.printOptions?.shippingLevel ?? dflt.shippingLevel);

const productConfig = {
  trim_size: `${dflt.trimIn?.w}x${dflt.trimIn?.h}`,
  interior_color: j.printOptions?.color ?? dflt.print?.color,
  interior_paper: j.printOptions?.stock ?? dflt.print?.stock,
  binding: j.printOptions?.binding ?? dflt.print?.binding,
  cover_finish: j.printOptions?.coverFinish ?? dflt.print?.coverFinish,
};

// Source URLs for Lulu to fetch: prefer presigned if present, else public CDN based on assetBase + R2 key.
const assetBase = dflt.assetBase || dflt.trimIn?.assetBase || 'https://admin.littleherolabs.com/api/assets/';
function toPublicUrl(ref) {
  if (!ref) return null;
  if (/^https?:\/\//i.test(String(ref))) return ref;
  return assetBase.replace(/\/+$/,'/') + String(ref).replace(/^\/+/,'');
}

const interiorSourceUrl = j.interiorSignedUrl || toPublicUrl(j.pdfR2Key) || j.bookPdfUrl || null;
const coverSourceUrl    = j.coverSignedUrl    || toPublicUrl(j.coverPdfR2Key) || j.coverPdfUrl || null;

if (!interiorSourceUrl || !coverSourceUrl) {
  throw new Error('Build Lulu Print Job Payload: missing interior or cover source URL');
}

// ---- Resolve pod_package_id ----
// 1) explicit per-job, 2) defaults.podPackageId, 3) defaults.trimIn.podPackageId, 4) smart fallback for our standard 8.5x8.5 book
const suggestedSku = '0850X0850FCPREPB080CW444MXX'; // 8.5x8.5, FC, PRE, PB, 80# CW, matte
const color       = j.printOptions?.color ?? dflt.print?.color;
const binding     = j.printOptions?.binding ?? dflt.print?.binding;
const stock       = j.printOptions?.stock ?? dflt.print?.stock;
const finish      = j.printOptions?.coverFinish ?? dflt.print?.coverFinish;
const trimW       = Number(dflt.trimIn?.w);
const trimH       = Number(dflt.trimIn?.h);

let podPackageId =
  j.printOptions?.podPackageId
  ?? dflt.podPackageId
  ?? dflt.trimIn?.podPackageId
  ?? (
    trimW === 8.5 && trimH === 8.5 &&
    String(color)   === 'premium-color' &&
    String(binding) === 'perfect-bound' &&
    String(stock)   === '80#-text' &&
    String(finish)  === 'matte'
      ? suggestedSku
      : null
  );

if (!podPackageId) {
  throw new Error('Build Lulu Print Job Payload: CONFIG.defaults.podPackageId (or printOptions.podPackageId) is required');
}

// Shipping address (Lulu expects shipping_address with phone_number)
const shipping_address = j.shippingAddress || j.shipping_address || {};
if (!shipping_address?.phone_number) {
  // Lulu requires phone_number; fail fast to avoid cryptic 4xx
  throw new Error('Build Lulu Print Job Payload: shipping_address.phone_number is required');
}

const lineItem = {
  title: j.title || 'Little Hero Book',
  quantity: qty,
  printable_normalization: {
    interior: { source_url: interiorSourceUrl },
    cover:    { source_url: coverSourceUrl },
    pod_package_id: podPackageId
  },
  print_options: productConfig
};

const payload = {
  shipping_level,
  contact_email: j.customer?.email || 'orders@littleherolabs.com',
  shipping_address,
  line_items: [ lineItem ]
};

return [{ json: { ...j, luluPayload: payload } }];

// Merge Lulu response with upstream context (supports two paths):
// A) Normal: HTTP response from "Submit Lulu Print Job" + upstream from "Build Lulu Print Job Payload"
// B) Idempotent skip: synthetic response from "Guard Lulu Submit" (already carries upstream)
const upstream = $items('Build Lulu Print Job Payload', 0, $runIndex)?.[0]?.json || $input.first().json || {};
const resp = $input.first().json || {};

const jobId = resp.id || resp.job_id || resp.data?.id || upstream.luluJobId;
const status = resp.status || resp.data?.status || upstream.luluStatus || 'CREATED';
const cost = resp.cost || resp.data?.cost || upstream.luluCost || null;
const eta = resp.estimated_ship_date || resp.data?.estimated_ship_date || upstream.estimatedShipDate || null;

return [{ json: { ...upstream, luluJobId: jobId, luluStatus: status, luluCost: cost, estimatedShipDate: eta } }];

const j = $input.first().json || {};
const manifest = {
  schema: 'lhb.run-manifest@v2.0',
  stage: '4-print-fulfillment',
  createdAt: new Date().toISOString(),
  orderId: j.orderId,
  artifacts: {
    interiorPdfR2Key: j.pdfR2Key || j.bookPdfUrl,
    coverPdfR2Key: j.coverPdfR2Key,
    coverPdfUrl: j.coverPdfUrl || null
  },
  lulu: {
    jobId: j.luluJobId,
    status: j.luluStatus,
    cost: j.luluCost,
    estimatedShipDate: j.estimatedShipDate
  }
};
const key = `book-mvp-simple-adventure/orders/${j.orderId}/manifests/4-manifest.json`;
return [{ json: { ...j, manifestKey: key, _manifest: manifest } }];

// Manual Trigger → Code: Emit W4 test payload from your 3A-manifest

// 1) Paste your manifest JSON here (from W3/W3A):
const manifest = {
  "schema":"lhb.run-manifest@v2.0",
  "amazonOrderId":"TEST-ORDER-010",
  "pages":{
    "p01":"book-mvp-simple-adventure/orders/TEST-ORDER-010/preview-images/p01.png",
    "p02":"book-mvp-simple-adventure/orders/TEST-ORDER-010/preview-images/p02.png",
    "p03":"book-mvp-simple-adventure/orders/TEST-ORDER-010/preview-images/p03.png",
    "p04":"book-mvp-simple-adventure/orders/TEST-ORDER-010/preview-images/p04.png",
    "p05":"book-mvp-simple-adventure/orders/TEST-ORDER-010/preview-images/p05.png",
    "p06":"book-mvp-simple-adventure/orders/TEST-ORDER-010/preview-images/p06.png",
    "p07":"book-mvp-simple-adventure/orders/TEST-ORDER-010/preview-images/p07.png",
    "p08":"book-mvp-simple-adventure/orders/TEST-ORDER-010/preview-images/p08.png",
    "p09":"book-mvp-simple-adventure/orders/TEST-ORDER-010/preview-images/p09.png",
    "p10":"book-mvp-simple-adventure/orders/TEST-ORDER-010/preview-images/p10.png",
    "p11":"book-mvp-simple-adventure/orders/TEST-ORDER-010/preview-images/p11.png",
    "p12":"book-mvp-simple-adventure/orders/TEST-ORDER-010/preview-images/p12.png",
    "p13":"book-mvp-simple-adventure/orders/TEST-ORDER-010/preview-images/p13.png",
    "p14":"book-mvp-simple-adventure/orders/TEST-ORDER-010/preview-images/p14.png"
  },
  "pdfGeneration":{
    "coverPdf":"book-mvp-simple-adventure/orders/TEST-ORDER-010/cover_TEST-ORDER-010.pdf"
  },
  "assetsUsed":{
    "dedicationBg":"book-mvp-simple-adventure/backgrounds/page00-dedication.png"
  }
};

// 2) Build the W4 payload
const orderId = manifest.amazonOrderId || manifest.orderId || "TEST-ORDER-010";

// This should match the CDN you already use in your templates:
const ASSET_BASE = "https://admin.littleherolabs.com/api/assets/";

// Collect interior page image URLs, sorted pNN:
const keys = Object.keys(manifest.pages || {}).sort(
  (a,b) => parseInt(a.slice(1),10) - parseInt(b.slice(1),10)
);
let pageImageUrls = keys.map(k => ASSET_BASE + manifest.pages[k]);
// Build required p00 explicitly (always required)
const p00FromDedication = manifest.assetsUsed?.dedicationBg ? (ASSET_BASE + manifest.assetsUsed.dedicationBg) : null;
const p00Preview = `${ASSET_BASE}book-mvp-simple-adventure/orders/${orderId}/preview-images/p00.png`;
const p00 = p00FromDedication || p00Preview;
pageImageUrls = [p00, ...pageImageUrls];

// If you truly have 15 pages (p00..p14), add p00. Otherwise, we insert a provisional p00.
// Option A: use the expected preview path for p00:
const maybeP00 = `${ASSET_BASE}book-mvp-simple-adventure/orders/${orderId}/preview-images/p00.png`;
// Option B: use the dedication background as a placeholder instead:
// const maybeP00 = ASSET_BASE + (manifest.assetsUsed?.dedicationBg || '');

if (pageImageUrls.length === 14) {
  pageImageUrls = [maybeP00, ...pageImageUrls];
}

// Cover: prefer R2 key so W4 presigns it
const coverPdfR2Key = manifest.pdfGeneration?.coverPdf;
const coverPdfUrl   = ASSET_BASE + (manifest.pdfGeneration?.coverPdf || "");

// (Optional) customer + shipping for Lulu payload
const shippingAddress = {
  name: "Test Recipient",
  street1: "123 Test St",
  city: "San Francisco",
  state_code: "CA",
  postcode: "94107",
  country_code: "US",
  phone_number: "555-555-5555",
  email: "test@example.com"
};
const customer = { name: "Test Customer", email: "test@example.com" };

return [{
  json: {
    orderId,
    title: "Little Hero Books — Test",
    pageImageUrls,
    coverPdfR2Key,           // preferred for W4
    // coverPdfUrl,           // uncomment to pass a direct URL instead
    shippingAddress,
    customer
  }
}];

// Guard Lulu Submit — skip if an existing Lulu job is already recorded in Supabase
// Input: JSON from "Supabase: get existing order" (HTTP GET, array or object)

function latest(name) {
  try { return ($items(name, 0, $runIndex)?.[0]?.json) || null; } catch { return null; }
}

// Prefer the most recent full context; fall back to validator
const upstream =
  latest('Build Lulu Print Job Payload') ||
  latest('Merge (after interior + meta)') ||
  latest('Validate & Normalize W4 Input') ||
  $json;

// Normalize Supabase GET result (array → object)
let rows = $input.first().json;
if (Array.isArray(rows)) rows = rows[0] || {};

const existingJobId  = rows?.luluJobId || rows?.lulu_job_id;
const existingStatus = rows?.lulu_status || rows?.status;

// Test mode? Bypass Lulu submit entirely.
const testMode = !!(upstream?.CONFIG?.defaults?.testMode || upstream?.testMode);
if (testMode) {
  const resp = { id: `TEST-${upstream.orderId || 'ORDER'}`, status: 'TEST_MODE' };
  return [{ json: { ...upstream, __skipLulu: true, ...resp } }];
}

// Existing job on record? Bypass and return a synthetic response compatible with downstream.
if (existingJobId) {
  const resp = { id: existingJobId, status: existingStatus || 'SUBMITTED' };
  return [{ json: { ...upstream, __skipLulu: true, ...resp } }];
}

// No-op (return no items) so the "bypass" branch stops here
// and only the real Lulu submit branch executes.
return [];

const resp = $input.first().json || {};
const access = resp.access_token || resp.token || resp.data?.access_token;
const expires = resp.expires_in || resp.data?.expires_in || null;
if (!access) throw new Error('SANDBOX token response missing access_token');
const issuedAt = new Date().toISOString();
return [{ json: { ...$json, luluAccessToken: access, luluTokenType: 'Bearer', luluTokenExpiresIn: expires, luluTokenIssuedAt: issuedAt } }];

const resp = $input.first().json || {};
const access = resp.access_token || resp.token || resp.data?.access_token;
const expires = resp.expires_in || resp.data?.expires_in || null;
if (!access) throw new Error('PRODUCTION token response missing access_token');
const issuedAt = new Date().toISOString();
return [{ json: { ...$json, luluAccessToken: access, luluTokenType: 'Bearer', luluTokenExpiresIn: expires, luluTokenIssuedAt: issuedAt } }];

// Centralized configuration & secrets (hardcoded per request)
// TODO: USE N8N CREDENTIALS for tokens/keys in production
/* PRODUCTION CONFIG */
const CONFIG = {
  pdfMonkey: {
    token: '2zpxHdmsse2ECXgVVtVR', // replace if you use a separate prod PDFMonkey token
    templateId: '5539DDB4-EC78-4AE9-A3FB-DB1E7F8DD172' // interior template (pages_html)
  },
  lulu: {
    apiBase: 'https://api.lulu.com',
    clientKey: 'REPLACE_WITH_LULU_CLIENT_KEY',
    clientSecret: 'REPLACE_WITH_LULU_CLIENT_SECRET',
    // base64(clientKey:clientSecret)
    basicAuth: null
  },
